/**
 * A Czech SPD bank-payment QR, as scanned off a real invoice.
 *
 * The currency must be CZK, EUR or BRL: getBankPaymentOfferCurrency returns null
 * for anything else, which silently empties the offer's recipient list.
 *
 * The PNG is generated once from SPD_PAYLOAD (`qrcode` package) and committed,
 * so the test feeds a real image through the app's own jsqr decoder.
 */
export const SPD_PAYLOAD =
  "SPD*1.0*ACC:CZ6508000000192000145399*AM:1.00*CC:CZK" +
  "*X-VS:1234567890*MSG:LINKY E2E TEST";

/** Fields that render as rows on the offer screens (AM/CC feed the header instead). */
export const SPD_ACCOUNT = "CZ6508000000192000145399";
export const SPD_VARIABLE_SYMBOL = "1234567890";
export const SPD_MESSAGE = "LINKY E2E TEST";

export const SPD_QR_PNG_BASE64 =
  "";
